/* =========================================================
   Math12 Hub V27 — Teacher Operations Pro
   Extends V26 without replacing Secure Exam V18 / Low Reads V19.
   ========================================================= */
const V27_SCHEMA=27;
const V27_ROSTER='rosterV27';
const V27_GROUPS='groupsV27';
const V27_TRANSFERS='transfersV27';
const V27_ATTEMPTS='attemptHistoryV27';
let v27GroupCache=new Map();
let v27TodayBusy=false;

function v27ClassRef(classId){return firebaseDb.collection('classes').doc(classId)}
function v27RosterRef(classId){return v27ClassRef(classId).collection(V27_ROSTER)}
function v27GroupsRef(classId){return v27ClassRef(classId).collection(V27_GROUPS)}
function v27TransfersRef(classId){return v27ClassRef(classId).collection(V27_TRANSFERS)}
function v27AttemptRef(classId,assignmentId){return firebaseAssignmentsRef(classId).doc(assignmentId).collection(V27_ATTEMPTS)}
function v27NormEmail(v=''){return String(v||'').trim().toLowerCase()}
function v27NormText(v=''){return String(v??'').trim()}
function v27SafeId(v=''){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)}
function v27RosterDocId(row={},i=0){let e=v27NormEmail(row.email);if(e)return `email-${v27SafeId(e)}`;let n=v27SafeId(row.name||'student');return `${n||'student'}-${String(i+1).padStart(3,'0')}`}
function v27LocalDateTimeValue(d){d=d instanceof Date?d:new Date(d||Date.now());if(Number.isNaN(d.getTime()))d=new Date();let pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function v27DefaultOpenValue(){let d=new Date(Date.now()+5*60000);return v27LocalDateTimeValue(d)}
function v27AssignmentIsOpen(a={},now=Date.now()){let o=firebaseToDate(a.opensAt),d=firebaseToDate(a.dueAt);return (!o||o.getTime()<=now)&&(!d||d.getTime()>=now)}
function v27AssignmentWindowText(a={}){let o=firebaseToDate(a.opensAt),d=firebaseToDate(a.dueAt),now=Date.now();if(o&&o.getTime()>now)return `Mở lúc ${firebaseDateText(a.opensAt)}`;if(d&&d.getTime()<now)return 'Đã đóng';return 'Đang mở'}
function v27AttemptNumber(x={}){return Math.max(1,Number(x.attemptNumber)||1)}
function v27MaxAttempts(a={}){return Math.min(5,Math.max(1,Number(a.maxAttempts)||1))}
function v27AttemptHistoryId(uid,n){return `${uid}__${String(Math.max(1,Number(n)||1)).padStart(3,'0')}`}

/* ---------- XLSX / CSV roster import ---------- */
function v27DownloadRosterTemplate(){
  const csv='Ho ten,Email,Nhom,Ghi chu\nNguyen Van A,nguyenvana@example.com,Nhom 1,\nTran Thi B,tranthib@example.com,Nhom 2,\n';
  const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mau-danh-sach-hoc-sinh-v27.csv';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800)
}
function v27ParseCSV(text=''){
  let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i],nx=text[i+1];if(ch==='"'){if(quoted&&nx==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&nx==='\n')i++;row.push(cell);cell='';if(row.some(x=>String(x).trim()))rows.push(row);row=[]}else cell+=ch}row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);return rows
}
function v27RowsToRoster(matrix=[]){
  if(!matrix.length)return[];let headers=(matrix[0]||[]).map(x=>v27NormText(x).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));let find=(arr)=>headers.findIndex(h=>arr.some(k=>h===k||h.includes(k)));let ni=find(['ho ten','hoten','name','ten hoc sinh','hoc sinh']),ei=find(['email','e-mail','mail']),gi=find(['nhom','group','to']),ci=find(['ghi chu','ghichu','note']);if(ni<0)ni=0;if(ei<0)ei=1;return matrix.slice(1).map((r,i)=>({name:v27NormText(r[ni]),email:v27NormEmail(r[ei]),groupName:gi>=0?v27NormText(r[gi]):'',note:ci>=0?v27NormText(r[ci]):'',sourceRow:i+2})).filter(r=>r.name||r.email)
}
async function v27ReadRosterFile(file){
  if(!file)throw new Error('Chưa chọn tệp.');let name=(file.name||'').toLowerCase();if(name.endsWith('.csv')||name.endsWith('.txt'))return v27RowsToRoster(v27ParseCSV(await file.text()));if(!window.XLSX)throw new Error('Thư viện đọc Excel chưa tải được. Hãy kiểm tra Internet hoặc lưu tệp Excel thành CSV UTF-8 rồi nhập lại.');let buf=await file.arrayBuffer(),wb=XLSX.read(buf,{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]],matrix=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});return v27RowsToRoster(matrix)
}
function v27OpenRosterImport(classId){
  if(!requireTeacher('Import danh sách học sinh'))return;openModal('Import học sinh • V27','Excel/CSV → danh sách dự kiến của lớp',`<div class="firebase-banner"><b>Không tạo tài khoản thay học sinh.</b> V27 lưu danh sách dự kiến; học sinh vẫn tự đăng ký Firebase và tham gia bằng mã lớp. Giáo viên có thể đối chiếu email sau khi các em tham gia.</div><div class="online-form mt"><label>Tệp .xlsx / .xls / .csv</label><input id="v27RosterFile" type="file" accept=".xlsx,.xls,.csv,text/csv"><label>Quy tắc cột</label><div class="cloud-sync-note">Hàng đầu là tiêu đề. Nên dùng: <b>Họ tên | Email | Nhóm | Ghi chú</b>. Email giúp đối chiếu chính xác với tài khoản học sinh.</div></div>`,`<button class="btn btn-soft" onclick="v27DownloadRosterTemplate()">↓ Tải mẫu CSV</button><button class="btn btn-soft" onclick="closeModal()">Hủy</button><button class="btn btn-blue" onclick="v27ImportRosterFile('${attrEsc(classId)}')">Import</button>`)
}
async function v27ImportRosterFile(classId){
  if(!requireTeacher('Import danh sách học sinh'))return;let file=document.getElementById('v27RosterFile')?.files?.[0];if(!file)return alert('Hãy chọn tệp Excel hoặc CSV.');try{let rows=await v27ReadRosterFile(file);if(!rows.length)return alert('Không đọc được học sinh nào từ tệp.');let emails=rows.map(r=>r.email).filter(Boolean),dup=emails.filter((e,i)=>emails.indexOf(e)!==i);if(dup.length&&!confirm(`Có ${new Set(dup).size} email bị lặp trong tệp. V27 sẽ gộp theo email và giữ dòng sau cùng. Tiếp tục?`))return;let unique=new Map();rows.forEach((r,i)=>unique.set(r.email||`__${i}`,r));rows=[...unique.values()];if(rows.length>500)return alert('V27 giới hạn 500 học sinh cho một lần import. Hãy chia tệp thành nhiều phần.');let cref=v27ClassRef(classId),members=await cref.collection('members').get(),byEmail=new Map(members.docs.map(d=>[v27NormEmail(d.data()?.email),d.id]).filter(x=>x[0]));for(let i=0;i<rows.length;i+=300){let b=firebaseDb.batch();rows.slice(i,i+300).forEach((r,j)=>{let idx=i+j,linkedUid=r.email?byEmail.get(r.email)||'':'',id=v27RosterDocId(r,idx);b.set(v27RosterRef(classId).doc(id),{name:r.name,email:r.email,emailNormalized:r.email,groupName:r.groupName||'',note:r.note||'',status:linkedUid?'linked':'pending',linkedUid:linkedUid||'',sourceFile:file.name||'',sourceRow:r.sourceRow||idx+2,schemaVersion:27,importedBy:firebaseUser.uid,updatedAt:firebaseServerTimestamp(),createdAt:firebaseServerTimestamp()},{merge:true})});await b.commit()}await firebaseAuditLog('class.roster.import',{classId,file:file.name||'',count:rows.length});closeModal();await v27OpenRosterManager(classId);examToast?.(`Đã import ${rows.length} học sinh dự kiến.`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27OpenRosterManager(classId){
  if(!requireTeacher('Danh sách dự kiến'))return;try{let [rSnap,mSnap]=await Promise.all([v27RosterRef(classId).orderBy('name').get(),v27ClassRef(classId).collection('members').get()]),members=mSnap.docs.map(d=>({uid:d.id,...d.data()})),byEmail=new Map(members.map(m=>[v27NormEmail(m.email),m]).filter(x=>x[0])),rows=rSnap.docs.map(d=>({id:d.id,...d.data()})),linked=0;let body=rows.map(r=>{let m=byEmail.get(v27NormEmail(r.email)),isLinked=!!m;linked+=isLinked?1:0;return `<tr><td><b>${esc(r.name||'—')}</b><br><small>${esc(r.email||'Chưa có email')}</small></td><td>${esc(r.groupName||'—')}</td><td><span class="v25-account-status ${isLinked?'active':'locked'}">${isLinked?'● Đã vào lớp':'○ Chưa liên kết'}</span>${isLinked?`<br><small>${esc(m.name||m.email||m.uid)}</small>`:''}</td><td>${esc(r.note||'')}</td><td><button class="btn btn-danger" onclick="v27DeleteRosterRow('${attrEsc(classId)}','${attrEsc(r.id)}')">Xóa</button></td></tr>`}).join('');openModal('Danh sách dự kiến • V27',`${linked}/${rows.length} đã đối chiếu theo email`,`<div class="firebase-banner"><b>Đối chiếu tự động theo email.</b> Danh sách này phục vụ vận hành lớp, không cấp quyền Firestore cho người chưa tham gia.</div><div class="table-wrap mt"><table class="table"><thead><tr><th>Học sinh</th><th>Nhóm dự kiến</th><th>Trạng thái</th><th>Ghi chú</th><th></th></tr></thead><tbody>${body||'<tr><td colspan="5">Chưa có danh sách dự kiến.</td></tr>'}</tbody></table></div>`,`<button class="btn btn-soft" onclick="v27DownloadRosterTemplate()">↓ Mẫu CSV</button><button class="btn btn-soft" onclick="v27OpenRosterImport('${attrEsc(classId)}')">Import thêm</button><button class="btn btn-soft" onclick="closeModal()">Đóng</button>`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27DeleteRosterRow(classId,id){if(!confirm('Xóa dòng dự kiến này? Không ảnh hưởng tài khoản/học sinh đã vào lớp.'))return;try{await v27RosterRef(classId).doc(id).delete();await v27OpenRosterManager(classId)}catch(err){alert(firebaseErrorText(err))}}

/* ---------- Student groups ---------- */
async function v27LoadGroups(classId,force=false){if(!force&&v27GroupCache.has(classId))return v27GroupCache.get(classId);let s=await v27GroupsRef(classId).orderBy('name').get(),rows=s.docs.map(d=>({id:d.id,...d.data()}));v27GroupCache.set(classId,rows);return rows}
function v27InvalidateGroups(classId){v27GroupCache.delete(classId)}
async function v27OpenGroupManager(classId){
  if(!requireTeacher('Quản lý nhóm học sinh'))return;try{let [groups,mSnap]=await Promise.all([v27LoadGroups(classId,true),v27ClassRef(classId).collection('members').get()]),members=mSnap.docs.map(d=>({uid:d.id,...d.data()})).filter(m=>m.status!=='suspended'),html=groups.map(g=>`<div class="v27-group-row"><div><b>${esc(g.name||'Nhóm')}</b><small>${(g.memberUids||[]).length} học sinh${g.note?` • ${esc(g.note)}`:''}</small></div><div class="online-actions"><button class="btn btn-soft" onclick="v27EditGroup('${attrEsc(classId)}','${attrEsc(g.id)}')">Sửa</button><button class="btn btn-danger" onclick="v27DeleteGroup('${attrEsc(classId)}','${attrEsc(g.id)}')">Xóa</button></div></div>`).join('');openModal('Nhóm học sinh • V27',`${groups.length} nhóm • ${members.length} học sinh hoạt động`,`<div class="firebase-banner"><b>Nhóm tùy chỉnh V27</b> dùng để giao bài cho một tập học sinh cố định. Khi giao, danh sách UID được “đóng băng” vào bài để lịch sử không thay đổi nếu sau này sửa nhóm.</div><div class="v27-group-list mt">${html||'<div class="online-empty">Chưa tạo nhóm tùy chỉnh.</div>'}</div>`,`<button class="btn btn-soft" onclick="closeModal()">Đóng</button><button class="btn btn-blue" onclick="v27EditGroup('${attrEsc(classId)}','')">＋ Tạo nhóm</button>`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27EditGroup(classId,groupId=''){
  try{let [mSnap,gSnap]=await Promise.all([v27ClassRef(classId).collection('members').get(),groupId?v27GroupsRef(classId).doc(groupId).get():Promise.resolve(null)]),g=gSnap?.exists?{id:gSnap.id,...gSnap.data()}:{name:'',memberUids:[],note:''},selected=new Set(g.memberUids||[]),rows=mSnap.docs.map(d=>{let m=d.data()||{},disabled=m.status==='suspended';return `<label class="v27-member-check ${disabled?'disabled':''}"><input type="checkbox" value="${attrEsc(d.id)}" ${selected.has(d.id)?'checked':''} ${disabled?'disabled':''}><span><b>${esc(m.name||m.email||d.id)}</b><small>${esc(m.email||'')}${disabled?' • đang tạm khóa':''}</small></span></label>`}).join('');openModal(groupId?'Sửa nhóm':'Tạo nhóm','V27 • nhóm tùy chỉnh',`<div class="online-form"><label>Tên nhóm</label><input id="v27GroupName" value="${attrEsc(g.name||'')}" placeholder="Ví dụ: Nhóm bồi dưỡng"><label>Ghi chú</label><input id="v27GroupNote" value="${attrEsc(g.note||'')}" placeholder="Không bắt buộc"></div><div id="v27GroupMembers" class="v27-member-grid mt">${rows||'<div class="online-empty">Lớp chưa có học sinh.</div>'}</div>`,`<button class="btn btn-soft" onclick="v27OpenGroupManager('${attrEsc(classId)}')">Quay lại</button><button class="btn btn-blue" onclick="v27SaveGroup('${attrEsc(classId)}','${attrEsc(groupId)}')">Lưu nhóm</button>`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27SaveGroup(classId,groupId=''){
  let name=v27NormText(document.getElementById('v27GroupName')?.value),note=v27NormText(document.getElementById('v27GroupNote')?.value),uids=[...document.querySelectorAll('#v27GroupMembers input[type=checkbox]:checked')].map(x=>x.value);if(!name)return alert('Nhập tên nhóm.');if(!uids.length)return alert('Chọn ít nhất một học sinh.');try{let ref=groupId?v27GroupsRef(classId).doc(groupId):v27GroupsRef(classId).doc();await ref.set({name,note,memberUids:uids,memberCount:uids.length,ownerId:firebaseUser.uid,schemaVersion:27,updatedAt:firebaseServerTimestamp(),...(groupId?{}:{createdAt:firebaseServerTimestamp()})},{merge:true});v27InvalidateGroups(classId);await firebaseAuditLog(groupId?'class.group.update':'class.group.create',{classId,groupId:ref.id,name,memberCount:uids.length});await v27OpenGroupManager(classId)}catch(err){alert(firebaseErrorText(err))}
}
async function v27DeleteGroup(classId,groupId){if(!confirm('Xóa nhóm này? Các bài đã giao theo nhóm không bị thay đổi.'))return;try{let s=await v27GroupsRef(classId).doc(groupId).get(),g=s.data()||{};await v27GroupsRef(classId).doc(groupId).delete();v27InvalidateGroups(classId);await firebaseAuditLog('class.group.delete',{classId,groupId,name:g.name||''});await v27OpenGroupManager(classId)}catch(err){alert(firebaseErrorText(err))}}
async function v27PopulateAssignmentGroups(classId){let sel=document.getElementById('fbAssignmentTarget');if(!sel)return;try{let groups=await v27LoadGroups(classId,false);groups.forEach(g=>{let o=document.createElement('option');o.value=`group:${g.id}`;o.textContent=`Nhóm tùy chỉnh • ${g.name} (${(g.memberUids||[]).length})`;sel.appendChild(o)});if(firebaseSmartTargetPreset&&[...sel.options].some(o=>o.value===firebaseSmartTargetPreset))sel.value=firebaseSmartTargetPreset}catch(err){console.warn('V27 groups',err)}}

/* ---------- Transfer between classes owned by the same teacher ---------- */
async function v27PruneUidFromGroups(classId,uid){
  try{let snap=await v27GroupsRef(classId).get(),affected=snap.docs.filter(d=>(d.data()?.memberUids||[]).includes(uid));if(!affected.length)return 0;let b=firebaseDb.batch();affected.forEach(d=>{let g=d.data()||{},uids=(g.memberUids||[]).filter(x=>x!==uid);b.set(d.ref,{memberUids:uids,memberCount:uids.length,schemaVersion:27,updatedAt:firebaseServerTimestamp()},{merge:true})});await b.commit();v27InvalidateGroups(classId);return affected.length}catch(err){console.warn('V27 prune groups',err);return 0}
}
async function v27OpenTransferStudent(classId){
  if(!requireTeacher('Chuyển học sinh giữa lớp'))return;try{let [mSnap]=await Promise.all([v27ClassRef(classId).collection('members').get()]),members=mSnap.docs.map(d=>({uid:d.id,...d.data()})).filter(m=>m.status!=='suspended'),targets=(firebaseOwnedClasses||[]).filter(c=>c.id!==classId&&c.status!=='trashed');if(!members.length)return alert('Lớp chưa có học sinh.');if(!targets.length)return alert('Cần có ít nhất một lớp khác do thầy/cô sở hữu.');openModal('Chuyển học sinh • V27','Giữ lịch sử ở lớp cũ, cấp quyền ở lớp mới',`<div class="firebase-banner warn"><b>Không di chuyển bài nộp cũ.</b> Bài nộp và điểm vẫn nằm ở lớp nguồn để đối soát. Học sinh được thêm vào lớp đích và mất quyền lớp nguồn.</div><div class="online-form mt"><label>Học sinh</label><select id="v27TransferUid">${members.map(m=>`<option value="${attrEsc(m.uid)}">${esc(m.name||m.email||m.uid)}${m.email?` • ${esc(m.email)}`:''}</option>`).join('')}</select><label>Lớp đích</label><select id="v27TransferTarget">${targets.map(c=>`<option value="${attrEsc(c.id)}">${esc(c.name||'Lớp học')}</option>`).join('')}</select><label>Ghi chú</label><input id="v27TransferNote" placeholder="Ví dụ: chuyển nhóm ôn tập"></div>`,`<button class="btn btn-soft" onclick="closeModal()">Hủy</button><button class="btn btn-blue" onclick="v27TransferStudent('${attrEsc(classId)}')">Chuyển lớp</button>`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27TransferStudent(sourceClassId){
  let uid=document.getElementById('v27TransferUid')?.value,targetClassId=document.getElementById('v27TransferTarget')?.value,note=v27NormText(document.getElementById('v27TransferNote')?.value);if(!uid||!targetClassId)return;try{let [sCls,tCls,mSnap,tMem]=await Promise.all([v27ClassRef(sourceClassId).get(),v27ClassRef(targetClassId).get(),v27ClassRef(sourceClassId).collection('members').doc(uid).get(),v27ClassRef(targetClassId).collection('members').doc(uid).get()]);if(!sCls.exists||!tCls.exists||!mSnap.exists)throw new Error('Dữ liệu lớp/học sinh không còn tồn tại.');let sc=sCls.data()||{},tc=tCls.data()||{},m=mSnap.data()||{};if(sc.ownerId!==firebaseUser.uid||tc.ownerId!==firebaseUser.uid)throw new Error('V27 chỉ chuyển trực tiếp giữa hai lớp cùng chủ sở hữu.');if(tMem.exists)return alert('Học sinh đã có trong lớp đích.');if(!confirm(`Chuyển “${m.name||m.email||uid}” từ “${sc.name||'lớp nguồn'}” sang “${tc.name||'lớp đích'}”?`))return;let transferRef=v27TransfersRef(sourceClassId).doc(),payload={id:transferRef.id,uid,name:m.name||'',email:m.email||'',sourceClassId,targetClassId,sourceClassName:sc.name||'',targetClassName:tc.name||'',note,status:'completed',ownerId:firebaseUser.uid,schemaVersion:27,transferredAt:firebaseServerTimestamp()},b=firebaseDb.batch();b.set(v27ClassRef(targetClassId).collection('members').doc(uid),{...m,classId:targetClassId,joinCode:tc.joinCode||'',status:'active',schemaVersion:27,transferredFrom:sourceClassId,transferredAt:firebaseServerTimestamp()},{merge:false});b.set(firebaseDb.collection('users').doc(uid).collection('memberships').doc(targetClassId),{classId:targetClassId,className:tc.name||'',joinCode:tc.joinCode||'',status:'active',schemaVersion:27,transferredFrom:sourceClassId,joinedAt:firebaseServerTimestamp()},{merge:true});b.delete(v27ClassRef(sourceClassId).collection('members').doc(uid));b.delete(firebaseDb.collection('users').doc(uid).collection('memberships').doc(sourceClassId));b.set(transferRef,payload,{merge:false});b.set(v27TransfersRef(targetClassId).doc(transferRef.id),payload,{merge:false});await b.commit();let groupsCleaned=await v27PruneUidFromGroups(sourceClassId,uid);await firebaseAuditLog('class.member.transfer',{uid,name:m.name||'',sourceClassId,targetClassId,sourceClassName:sc.name||'',targetClassName:tc.name||'',groupsCleaned});firebaseV19InvalidateClass(sourceClassId);firebaseV19InvalidateClass(targetClassId);await firebaseLoadMemberships();closeModal();await firebaseShowClass(sourceClassId);alert(`Đã chuyển học sinh sang lớp “${tc.name||'lớp đích'}”.`)}catch(err){alert(firebaseErrorText(err))}
}
async function v27OpenTransferHistory(classId){
  if(!requireTeacher('Lịch sử chuyển lớp'))return;try{let s=await v27TransfersRef(classId).orderBy('transferredAt','desc').limit(100).get(),rows=s.docs.map(d=>d.data()||{}),html=rows.map(x=>`<div class="audit-row"><div><b>${esc(x.name||x.email||x.uid||'Học sinh')}</b><small>${esc(x.sourceClassName||x.sourceClassId)} → ${esc(x.targetClassName||x.targetClassId)}${x.note?` • ${esc(x.note)}`:''}</small></div><span>${esc(firebaseDateText(x.transferredAt))}</span></div>`).join('');openModal('Lịch sử chuyển lớp • V27',`${rows.length} bản ghi gần nhất`,`<div class="audit-list">${html||'<div class="online-empty">Chưa có lịch sử chuyển lớp.</div>'}</div>`,'<button class="btn btn-soft" onclick="closeModal()">Đóng</button>')}catch(err){alert(firebaseErrorText(err))}
}

