/* ---------- audit labels ---------- */
const v27OldAuditLabel=typeof firebaseAuditActionLabel==='function'?firebaseAuditActionLabel:null;
firebaseAuditActionLabel=function(a=''){let m={'class.roster.import':'Import danh sách dự kiến','class.group.create':'Tạo nhóm học sinh','class.group.update':'Sửa nhóm học sinh','class.group.delete':'Xóa nhóm học sinh','class.member.transfer':'Chuyển học sinh giữa lớp','assignment.create':'Giao bài V27','assignment.retry.grant':'Cấp thêm lượt làm','assignment.settings.update':'Sửa lịch/số lượt bài giao'};return m[a]||(v27OldAuditLabel?v27OldAuditLabel(a):a)};

/* One-time V27 migration for teacher-owned classes: add opensAt/maxAttempts to legacy assignments. */
const v27OriginalLoadMemberships=typeof firebaseLoadMemberships==='function'?firebaseLoadMemberships:null;
if(v27OriginalLoadMemberships)firebaseLoadMemberships=async function(){
  let r=await v27OriginalLoadMemberships();
  if(isTeacherRole?.()&&firebaseUser&&firebaseDb){
    for(const c of (firebaseOwnedClasses||[]).filter(x=>!x.teacherOpsV27Ready)){
      try{await v27NormalizeAssignments(c.id);await v27ClassRef(c.id).set({teacherOpsV27Ready:true,schemaVersion:27,updatedAt:firebaseServerTimestamp()},{merge:true});c.teacherOpsV27Ready=true}catch(err){console.warn('V27 one-time class migration',c.id,err)}
    }
  }
  return r;
};
